const f=await glob({pattern:"data/orders/*.json"});
const rep={changed:[],skipped:[],odd:[]};
for(const p of f.files){
 const r=await read({path:p});
 const raw=r.content;
 let o;try{o=JSON.parse(raw)}catch(e){rep.odd.push([p,'parse']);continue}
 if(o.status!=="paid"){rep.skipped.push(o.status);continue}
 if(!Array.isArray(o.items)||o.items.some(i=>typeof i.qty!=="number")){rep.odd.push([p,'items']);continue}
 o.itemCount=o.items.reduce((s,i)=>s+i.qty,0);
 const nl=raw.endsWith("\n")?"\n":"";
 await write({path:p,content:JSON.stringify(o,null,2)+nl});
 rep.changed.push(p.split('/').pop());
}
return {changed:rep.changed.length,skipped:rep.skipped,odd:rep.odd};

