const f=await glob({pattern:"data/orders/*.json"});
let n=0;
for(const p of f.files){
 const raw=(await read({path:p})).content;
 const o=JSON.parse(raw);
 if(o.status==="paid"&&!raw.endsWith("\n")){await write({path:p,content:raw+"\n"});n++}
}
const d=await bash({command:"git diff --stat"});
return {n,tail:d.stdout.split("\n").slice(-2)};

